export const layers = [
  { n: "00", title: "Energy & Power Grid", short: "Power", color: "#d6ff5f", thesis: "AI begins with electricity. Generation, transmission, cooling and power management are becoming the physical constraint on compute growth.", explainer: "Data centers cannot run on software alone. They need reliable electricity around the clock, high-voltage connections, backup systems and cooling that removes enormous amounts of heat. As AI clusters grow, securing power can determine where—and how quickly—new capacity is built.", value: "Owners of scarce generation, grid equipment and mission-critical cooling can benefit before a model produces a single token.", risk: "Slow permitting, regulated returns, falling demand or rapid efficiency gains could limit the upside.", includes: ["Generation", "Grid equipment", "Cooling", "Power management"], signals: ["Data-center power demand is reshaping utility planning", "Grid interconnection queues remain a deployment constraint"], companies: ["VRT", "GEV", "ETN"] },
  { n: "01", title: "Silicon & Manufacturing", short: "Silicon", color: "#78e7ff", thesis: "The hardest-to-replicate tools and processes sit deep inside the semiconductor supply chain, where technical leadership compounds over decades.", explainer: "Every AI chip begins as a design and becomes physical through an extraordinarily complex manufacturing chain. Specialized design software, lithography machines, foundries, process-control tools and advanced packaging must all work together at atomic-scale precision.", value: "The strongest economics often sit with suppliers whose technology is required at every leading-edge node and cannot be duplicated quickly.", risk: "Semiconductor cycles, export controls, customer concentration and manufacturing delays remain central risks.", includes: ["Lithography", "Foundries", "EDA software", "Process control"], signals: ["Leading-edge nodes require rising capital intensity", "Advanced packaging is now a strategic bottleneck"], companies: ["ASML", "TSM", "CDNS"] },
  { n: "02", title: "Compute & Networking", short: "Compute", color: "#a894ff", thesis: "Accelerators, memory and high-speed networks turn silicon into usable AI capacity. Performance-per-watt is the key economic metric.", explainer: "Training and serving modern models requires thousands of accelerators to behave like one machine. GPUs perform the calculations, high-bandwidth memory keeps data close, and networking moves information between chips without creating expensive idle time.", value: "Platforms combining chips, networking and software can capture more value because customers buy a working system—not isolated hardware.", risk: "Custom chips, changing model architectures, supply normalization and more efficient inference could weaken pricing power.", includes: ["Accelerators", "Networking", "Memory", "Interconnect"], signals: ["Cluster scale is moving from thousands to hundreds of thousands of chips", "Networking is taking a larger share of AI infrastructure spend"], companies: ["NVDA", "AVGO", "ANET"] },
  { n: "03", title: "Cloud & Data Centers", short: "Cloud", color: "#ffb86b", thesis: "Hyperscalers aggregate infrastructure, distribution and developer ecosystems—turning massive capital expenditure into rented intelligence.", explainer: "Most companies will not build their own AI supercomputer. Cloud platforms finance the infrastructure, operate it globally and rent access through developer-friendly services. Data-center operators provide the specialized real estate, connectivity and power underneath them.", value: "Scale lowers unit costs, while enterprise relationships and developer ecosystems make the cloud a powerful distribution layer for AI.", risk: "Heavy capital expenditure, capacity shortages, price competition and workload portability can pressure returns.", includes: ["Hyperscale cloud", "Colocation", "Data platforms", "AI services"], signals: ["Cloud providers are accelerating AI infrastructure investment", "Capacity access is becoming a competitive advantage"], companies: ["MSFT", "AMZN", "GOOGL"] },
  { n: "04", title: "Foundation Models", short: "Models", color: "#ff7ab6", thesis: "Foundation models convert compute and data into general intelligence. Distribution, proprietary data and inference economics may matter more than leaderboard position.", explainer: "Foundation models are general-purpose systems trained on broad datasets and adapted to many tasks. They provide the language, reasoning, image and multimodal capabilities that developers access through APIs or open model weights.", value: "Long-term advantage may come from distribution, proprietary feedback data, developer adoption and better output at lower inference cost.", risk: "Rapid commoditization, open-source competition, regulation and weak switching costs could move profits to adjacent layers.", includes: ["Language models", "Multimodal models", "Model tooling", "Inference"], signals: ["Model performance gaps continue to narrow", "Inference cost and distribution increasingly shape adoption"], companies: ["GOOGL", "META", "MSFT"] },
  { n: "05", title: "Applications & Agents", short: "Apps", color: "#6fffc5", thesis: "The application layer translates model capability into measurable workflows. Winners need proprietary context, trusted distribution and high switching costs.", explainer: "Applications combine models with company data, interfaces and workflow logic. Agents go further: they can plan a task, use tools and complete multiple actions with limited supervision. This is where AI becomes visible to the end customer.", value: "Applications capture durable value when they own the workflow, hold trusted data and deliver measurable outcomes—not merely add a chatbot.", risk: "Features can be copied, model providers may move up the stack, and uncertain ROI can slow enterprise adoption.", includes: ["Enterprise agents", "Vertical software", "Developer tools", "Consumer AI"], signals: ["Enterprise buyers are shifting from pilots toward workflow deployment", "Incumbents are embedding agents into systems of record"], companies: ["PLTR", "NOW", "CRM"] },
];
